<script>
  function switchPortalTab(target) {
    const loginTab = document.getElementById('tab-content-login');
    const registerTab = document.getElementById('tab-content-register');
    const btnLogin = document.getElementById('tab-btn-login');
    const btnRegister = document.getElementById('tab-btn-register');

    if (target === 'login') {
      loginTab.classList.remove('hidden');
      registerTab.classList.add('hidden');
      btnLogin.className = 'flex-1 flex items-center justify-center gap-2 py-2.5 px-4 rounded font-headline-sm text-headline-sm transition-all bg-[#0a3d91] text-white shadow-sm hover:bg-[#061936]';
      btnRegister.className = 'flex-1 flex items-center justify-center gap-2 py-2.5 px-4 rounded font-headline-sm text-headline-sm transition-all text-[#061936] hover:bg-[#0a3d91] hover:text-white';
    } else {
      registerTab.classList.remove('hidden');
      loginTab.classList.add('hidden');
      btnRegister.className = 'flex-1 flex items-center justify-center gap-2 py-2.5 px-4 rounded font-headline-sm text-headline-sm transition-all bg-[#0a3d91] text-white shadow-sm hover:bg-[#061936]';
      btnLogin.className = 'flex-1 flex items-center justify-center gap-2 py-2.5 px-4 rounded font-headline-sm text-headline-sm transition-all text-[#061936] hover:bg-[#0a3d91] hover:text-white';
    }
  }

  function togglePassVisibility(inputId) {
    const input = document.getElementById(inputId);
    const icon = document.getElementById('login-pass-icon');
    if (input.type === 'password') {
      input.type = 'text';
      icon.innerText = 'visibility_off';
    } else {
      input.type = 'password';
      icon.innerText = 'visibility';
    }
  }

  function handleAuthSubmit(e, formType) {
    e.preventDefault();
    if (formType === 'login') {
      alert('Authentication request routed to San Pedro Laguna Security Gateway. Verified credential required for wholesale dispatch.');
    } else {
      const randomRef = 'DSAM-APP-' + Math.floor(1000 + Math.random() * 9000);
      alert('Commercial Application successfully registered! Generated Reference Number: ' + randomRef + '\n\nExecutive Admin Board review SLA: 24 to 48 hours.');
      document.getElementById('ref-input').value = randomRef;
      document.getElementById('active-ref').innerText = randomRef;
      switchPortalTab('login');
    }
  }

  function handleTrackStatus(e) {
    e.preventDefault();
    const inputVal = document.getElementById('ref-input').value.trim();
    if (inputVal) {
      document.getElementById('active-ref').innerText = inputVal.toUpperCase();
    }
  }
</script></main></body></html>




